def verify_task_completion(initial_db_path: str, final_db_path: str, final_answer: str | None = None) -> dict:
    import sqlite3
    import re

    def safe_query(db_path: str, query: str, params: tuple = ()) -> list:
        """Safely execute a read-only query on the given SQLite database.

        Returns an empty list on any error.
        """
        try:
            conn = sqlite3.connect(f"file:{db_path}?mode=ro", uri=True)
            cur = conn.cursor()
            cur.execute(query, params)
            rows = cur.fetchall()
            conn.close()
            return rows
        except Exception:
            return []

    # 1. Find primary user's active cart (user_id = 1) in initial and final DBs
    cart_query = "SELECT id FROM carts WHERE user_id = ? AND status = 'active'"
    initial_carts = safe_query(initial_db_path, cart_query, (1,))
    final_carts = safe_query(final_db_path, cart_query, (1,))

    if len(final_carts) != 1:
        # No active cart or multiple active carts in final state -> cannot verify
        return {"result": "others"}

    final_cart_id = final_carts[0][0]

    # We do not strictly need the initial cart id, but we use it to compare items.
    if len(initial_carts) != 1:
        # Inconsistent initial state, be conservative
        return {"result": "others"}

    initial_cart_id = initial_carts[0][0]

    # 2. Identify qualifying 'wireless noise cancelling headphones' products.
    #    Criteria:
    #      - category_id = 2 (Headphones)
    #      - title or description contains both 'wireless' and 'noise cancell' substrings (case-insensitive)

    products_query = (
        "SELECT p.id, p.title, p.description "
        "FROM products p "
        "WHERE p.category_id = 2"
    )
    products = safe_query(initial_db_path, products_query, ())

    if not products:
        return {"result": "others"}

    qualifying_product_ids = []
    for pid, title, desc in products:
        title_text = title or ""
        desc_text = desc or ""
        text = (title_text + " " + desc_text).lower()
        # Use simple substring search for determinism
        if "wireless" in text and "noise cancell" in text:
            qualifying_product_ids.append(pid)

    if not qualifying_product_ids:
        # No products match the search semantics
        return {"result": "others"}

    # 3. For these products, get their average_rating from product_aggregates
    #    and select the top-rated one. Tie-breaker: lowest product_id.

    placeholders = ",".join(["?"] * len(qualifying_product_ids))
    aggregates_query = (
        f"SELECT product_id, average_rating "
        f"FROM product_aggregates "
        f"WHERE product_id IN ({placeholders})"
    )
    aggregates = safe_query(initial_db_path, aggregates_query, tuple(qualifying_product_ids))

    if not aggregates:
        return {"result": "others"}

    rating_by_product = {}
    for prod_id, avg_rating in aggregates:
        # Exclude NULL ratings
        if avg_rating is not None:
            rating_by_product[int(prod_id)] = float(avg_rating)

    # Filter to only qualifying products that have ratings
    rated_qualifying = [(pid, rating_by_product[pid]) for pid in qualifying_product_ids if pid in rating_by_product]

    if not rated_qualifying:
        return {"result": "others"}

    # Determine top-rated product: highest average_rating, tie -> lowest product_id
    rated_qualifying.sort(key=lambda x: (-x[1], x[0]))
    top_product_id, top_product_rating = rated_qualifying[0]

    # 4. For this top product, find active offers under $200 (USD) and pick cheapest
    offers_query = (
        "SELECT id, price, currency, is_active "
        "FROM product_offers "
        "WHERE product_id = ?"
    )
    offers = safe_query(initial_db_path, offers_query, (top_product_id,))

    if not offers:
        return {"result": "others"}

    qualifying_offers = []
    for offer_id, price, currency, is_active in offers:
        if currency != "USD":
            continue
        # Defensive checks
        try:
            price_val = float(price)
        except (TypeError, ValueError):
            continue
        if price_val < 200.0 and is_active == 1:
            qualifying_offers.append((offer_id, price_val))

    if not qualifying_offers:
        # No offer under $200 -> task cannot be satisfied
        return {"result": "others"}

    # Choose the cheapest offer; tie-breaker: lowest offer_id
    qualifying_offers.sort(key=lambda x: (x[1], x[0]))
    expected_offer_id = qualifying_offers[0][0]

    # 5. Read initial and final cart_items for the user's active cart
    cart_items_query = "SELECT product_offer_id, quantity FROM cart_items WHERE cart_id = ?"

    initial_items = safe_query(initial_db_path, cart_items_query, (initial_cart_id,))
    final_items = safe_query(final_db_path, cart_items_query, (final_cart_id,))

    if final_items is None:
        return {"result": "others"}

    # Build dictionaries for easy lookup
    def build_offer_qty_map(rows):
        mapping = {}
        for offer_id, qty in rows or []:
            try:
                oid = int(offer_id)
                q = int(qty)
            except (TypeError, ValueError):
                # Malformed row; ignore this row for safety
                continue
            # If multiple rows per offer exist (should not normally happen), sum quantities
            mapping[oid] = mapping.get(oid, 0) + q
        return mapping

    initial_map = build_offer_qty_map(initial_items)
    final_map = build_offer_qty_map(final_items)

    # 6. Verify that in the final state, the expected offer is present with quantity exactly 1
    final_qty = final_map.get(expected_offer_id)
    if final_qty != 1:
        # Either not present or wrong quantity
        return {"result": "others"}

    # 7. Ensure that we can attribute this to the agent adding 1 unit under this task.
    # We must be conservative about interpreting changes:
    # - If the offer did not exist initially and now has quantity 1 -> clearly added 1.
    # - If the offer existed initially with quantity 1 and still is 1 -> no change; cannot be sure the agent performed the task now.
    # - If the quantity changed from something else to 1 -> ambiguous, treat as others.

    initial_qty = initial_map.get(expected_offer_id)

    if initial_qty is None:
        # Newly added with quantity 1 -> acceptable
        return {"result": "complete"}

    # If there was already 1 in the cart before, or any other previous quantity, we are not 100% sure
    # the agent executed the requested action during this episode.
    return {"result": "others"}

def verify_task_completion(initial_db_path: str, final_db_path: str, final_answer: str | None = None) -> dict:
    import sqlite3
    import re

    # Helper to safely query database in read-only mode
    def safe_query(db_path: str, query: str, params: tuple = ()) -> list:
        try:
            conn = sqlite3.connect(f"file:{db_path}?mode=ro", uri=True)
            cursor = conn.cursor()
            cursor.execute(query, params)
            rows = cursor.fetchall()
            conn.close()
            return rows
        except Exception:
            return []

    # 1. Get primary user's id from both DBs and ensure consistency
    user_rows_initial = safe_query(
        initial_db_path,
        "SELECT id FROM users WHERE username = ?",
        ("primary_user",),
    )
    user_rows_final = safe_query(
        final_db_path,
        "SELECT id FROM users WHERE username = ?",
        ("primary_user",),
        )

    if len(user_rows_initial) != 1 or len(user_rows_final) != 1:
        return {"result": "others"}

    user_id_initial = user_rows_initial[0][0]
    user_id_final = user_rows_final[0][0]

    # The user id should be the same between DBs
    if user_id_initial != user_id_final:
        return {"result": "others"}

    user_id = user_id_initial

    # 2. Ensure no wishlist with the target name existed initially for this user
    initial_wishlists = safe_query(
        initial_db_path,
        "SELECT id FROM wishlists WHERE user_id = ? AND name = ?",
        (user_id, "Kitchen Upgrades 2025"),
    )
    if len(initial_wishlists) != 0:
        # If it already existed, we cannot be certain the agent created it now
        return {"result": "others"}

    # 3. In final DB, verify exactly one wishlist with the given name for this user
    final_wishlists = safe_query(
        final_db_path,
        "SELECT id FROM wishlists WHERE user_id = ? AND name = ?",
        (user_id, "Kitchen Upgrades 2025"),
    )
    if len(final_wishlists) != 1:
        return {"result": "others"}

    wishlist_id = final_wishlists[0][0]

    # 4. Identify air fryer products in final DB
    # Find category id for 'Air Fryers'
    air_cat_rows = safe_query(
        final_db_path,
        "SELECT id FROM product_categories WHERE name = ?",
        ("Air Fryers",),
    )
    if len(air_cat_rows) != 1:
        # Cannot determine air fryer category reliably
        return {"result": "others"}

    air_cat_id = air_cat_rows[0][0]

    # All products that are air fryers
    air_products = safe_query(
        final_db_path,
        "SELECT id FROM products WHERE category_id = ?",
        (air_cat_id,),
    )
    air_product_ids = [row[0] for row in air_products]

    if len(air_product_ids) == 0:
        # No air fryer products found; task cannot be satisfied
        return {"result": "others"}

    # 5. For each air fryer product, ensure at least one active offer under $150 exists
    #   and gather its best sales_rank.
    # We will do this using SQL with GROUP BY to keep it deterministic.

    # Build a parameter placeholder string for IN clause
    placeholders = ",".join(["?"] * len(air_product_ids))

    # Get products with at least one active offer under 150
    offer_query = (
        "SELECT p.id AS product_id, MIN(o.price) AS min_price "
        "FROM products p "
        "JOIN product_offers o ON p.id = o.product_id "
        f"WHERE p.id IN ({placeholders}) AND o.is_active = 1 AND o.price < ? "
        "GROUP BY p.id"
    )

    offer_params = tuple(air_product_ids) + (150.0,)
    qualifying_offers = safe_query(final_db_path, offer_query, offer_params)

    if len(qualifying_offers) < 3:
        # Fewer than 3 air fryers under $150 exist, so task cannot be fully satisfied
        return {"result": "others"}

    qualifying_ids = [row[0] for row in qualifying_offers]

    # 6. Get sales_rank for qualifying products
    placeholders_q = ",".join(["?"] * len(qualifying_ids))
    rank_query = (
        "SELECT product_id, sales_rank "
        "FROM product_aggregates "
        f"WHERE product_id IN ({placeholders_q})"
    )

    rank_rows = safe_query(final_db_path, rank_query, tuple(qualifying_ids))
    # Build dict product_id -> sales_rank (may be None if missing or NULL)
    rank_map = {pid: None for pid in qualifying_ids}
    for pid, sr in rank_rows:
        rank_map[pid] = sr

    # 7. Determine the top 3 best-selling among qualifying_ids
    # Sorting rules:
    #   - Primary: sales_rank ascending, treating NULL as worse than any number
    #   - Secondary: product_id ascending for deterministic tie-breaking

    def sort_key(pid):
        sr = rank_map.get(pid)
        if sr is None:
            # Use a large sentinel for NULL ranks
            return (10**12, pid)
        # Ensure numeric
        try:
            sr_val = float(sr)
        except Exception:
            # If somehow non-numeric, treat as worst
            return (10**12, pid)
        return (sr_val, pid)

    sorted_ids = sorted(qualifying_ids, key=sort_key)

    if len(sorted_ids) < 3:
        # Defensive check; should already be covered but keep it safe
        return {"result": "others"}

    top_three_ids = sorted_ids[:3]

    # 8. Check that the new wishlist contains all three of these product_ids
    wishlist_items_rows = safe_query(
        final_db_path,
        "SELECT product_id FROM wishlist_items WHERE wishlist_id = ?",
        (wishlist_id,),
    )

    if not wishlist_items_rows:
        return {"result": "others"}

    wishlist_product_ids = [row[0] for row in wishlist_items_rows]

    for pid in top_three_ids:
        if pid not in wishlist_product_ids:
            return {"result": "others"}

    # All checks passed deterministically
    return {"result": "complete"}
